-- LabelProof isolated schema: browser publishable key, RLS and server role checks.
-- Apply this file first, then 002_review_bindings.sql.
create schema if not exists lp_private;
revoke all on schema lp_private from public;
grant usage on schema lp_private to authenticated;
create table public.lp_orgs (id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 80),created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create table public.lp_members (org_id uuid references public.lp_orgs(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text not null check(role in ('admin','reviewer','uploader')),primary key(org_id,user_id));
create table public.lp_snapshots (org_id uuid primary key references public.lp_orgs(id) on delete cascade,version bigint not null default 0,payload jsonb not null,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.lp_audit (id uuid primary key default gen_random_uuid(),org_id uuid references public.lp_orgs(id) on delete cascade,actor uuid references auth.users(id),action text not null,details jsonb not null default '{}',at timestamptz not null default now());
create table public.lp_review_events (id uuid primary key default gen_random_uuid(),org_id uuid not null references public.lp_orgs(id) on delete cascade,assessment_id text not null,action text not null check(action in ('comment','assign','request_rescan','approve','reject')),note text not null check(length(note) between 1 and 5000),actor uuid not null references auth.users(id),at timestamptz not null default now());
alter table public.lp_orgs enable row level security;
alter table public.lp_members enable row level security;
alter table public.lp_snapshots enable row level security;
alter table public.lp_audit enable row level security;
alter table public.lp_review_events enable row level security;
create function lp_private.member_role(organization uuid) returns text language sql stable security definer set search_path='' as $$ select role from public.lp_members where org_id=organization and user_id=(select auth.uid()) $$;
revoke all on function lp_private.member_role(uuid) from public;
grant execute on function lp_private.member_role(uuid) to authenticated;
create policy org_read on public.lp_orgs for select to authenticated using(lp_private.member_role(id) is not null);
create policy member_read on public.lp_members for select to authenticated using(lp_private.member_role(org_id) is not null);
create policy snapshot_read on public.lp_snapshots for select to authenticated using(lp_private.member_role(org_id) is not null);
create policy audit_read on public.lp_audit for select to authenticated using(lp_private.member_role(org_id) is not null);
create policy review_read on public.lp_review_events for select to authenticated using(lp_private.member_role(org_id) is not null);
grant select on public.lp_orgs,public.lp_members,public.lp_snapshots,public.lp_audit,public.lp_review_events to authenticated;
revoke all on public.lp_orgs,public.lp_members,public.lp_snapshots,public.lp_audit,public.lp_review_events from anon;
-- Privileged implementations live in a non-exposed schema, verify membership on every call.
create function lp_private.create_org(org_name text) returns uuid language plpgsql security definer set search_path='' as $$ declare org uuid; begin if auth.uid() is null then raise exception 'Sign in required';end if;if length(trim(org_name)) not between 1 and 80 then raise exception 'Invalid name';end if;if(select count(*) from public.lp_orgs where created_by=auth.uid())>=5 then raise exception 'Organization limit reached';end if;insert into public.lp_orgs(name,created_by)values(trim(org_name),auth.uid())returning id into org;insert into public.lp_members values(org,auth.uid(),'admin');insert into public.lp_audit(org_id,actor,action)values(org,auth.uid(),'organization_created');return org;end $$;
create function public.lp_create_org(org_name text) returns uuid language sql security invoker set search_path='' as $$ select lp_private.create_org(org_name) $$;
create function lp_private.set_member(organization uuid,member uuid,member_role text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null or lp_private.member_role(organization) is distinct from 'admin' then raise exception 'Administrator required';end if;if member_role not in('admin','reviewer','uploader') then raise exception 'Invalid role';end if;if member=auth.uid() and member_role<>'admin' then raise exception 'Cannot downgrade yourself';end if;insert into public.lp_members values(organization,member,member_role)on conflict(org_id,user_id)do update set role=excluded.role;insert into public.lp_audit(org_id,actor,action,details)values(organization,auth.uid(),'member_role_updated',jsonb_build_object('user',member,'role',member_role));end $$;
create function public.lp_set_member(organization uuid,member uuid,member_role text) returns void language sql security invoker set search_path='' as $$ select lp_private.set_member(organization,member,member_role) $$;
create function lp_private.save_snapshot(organization uuid,expected_version bigint,payload jsonb) returns bigint language plpgsql security definer set search_path='' as $$ declare current_version bigint;begin if auth.uid() is null or lp_private.member_role(organization) is null then raise exception 'Organization access required';end if;if payload is null or pg_column_size(payload)>10000000 or coalesce(payload->>'format','')<>'labelproof-workspace' or coalesce(jsonb_typeof(payload->'scans'),'')<>'array' or coalesce(jsonb_typeof(payload->'images'),'')<>'array' or coalesce(jsonb_typeof(payload->'assessments'),'')<>'array' then raise exception 'Invalid workspace payload';end if;perform pg_advisory_xact_lock(hashtextextended(organization::text,0));select version into current_version from public.lp_snapshots where org_id=organization;current_version:=coalesce(current_version,0);if current_version<>expected_version then raise exception 'Version conflict: download newest cloud snapshot';end if;insert into public.lp_snapshots(org_id,version,payload,updated_by)values(organization,current_version+1,payload,auth.uid())on conflict(org_id)do update set version=excluded.version,payload=excluded.payload,updated_by=excluded.updated_by,updated_at=now();insert into public.lp_audit(org_id,actor,action,details)values(organization,auth.uid(),'workspace_saved',jsonb_build_object('version',current_version+1));return current_version+1;end $$;
create function public.lp_save_snapshot(organization uuid,expected_version bigint,payload jsonb) returns bigint language sql security invoker set search_path='' as $$ select lp_private.save_snapshot(organization,expected_version,payload) $$;
create function lp_private.review(organization uuid,assessment text,review_action text,review_note text) returns uuid language plpgsql security definer set search_path='' as $$ declare event uuid; begin if auth.uid() is null or lp_private.member_role(organization) is null then raise exception 'Organization access required';end if;if review_action in('approve','reject','assign') and lp_private.member_role(organization) not in('reviewer','admin') then raise exception 'Reviewer role required';end if;if not exists(select 1 from public.lp_snapshots s,jsonb_array_elements(s.payload->'assessments') a where s.org_id=organization and a->>'id'=assessment)then raise exception 'Assessment not in cloud workspace';end if;insert into public.lp_review_events(org_id,assessment_id,action,note,actor)values(organization,assessment,review_action,review_note,auth.uid())returning id into event;insert into public.lp_audit(org_id,actor,action,details)values(organization,auth.uid(),'review_recorded',jsonb_build_object('assessment',assessment,'event',event));return event;end $$;
create function public.lp_review(organization uuid,assessment text,review_action text,review_note text) returns uuid language sql security invoker set search_path='' as $$ select lp_private.review(organization,assessment,review_action,review_note) $$;
revoke all on all functions in schema lp_private from public;
grant execute on all functions in schema lp_private to authenticated;
revoke all on function public.lp_create_org(text),public.lp_set_member(uuid,uuid,text),public.lp_save_snapshot(uuid,bigint,jsonb),public.lp_review(uuid,text,text,text) from public;
grant execute on function public.lp_create_org(text),public.lp_set_member(uuid,uuid,text),public.lp_save_snapshot(uuid,bigint,jsonb),public.lp_review(uuid,text,text,text) to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('labelproof-evidence','labelproof-evidence',false,12582912,array['image/jpeg','image/png','image/webp']);
create policy evidence_read on storage.objects for select to authenticated using(bucket_id='labelproof-evidence' and lp_private.member_role(((storage.foldername(name))[1])::uuid) is not null);
create policy evidence_upload on storage.objects for insert to authenticated with check(bucket_id='labelproof-evidence' and lp_private.member_role(((storage.foldername(name))[1])::uuid) is not null);
create policy evidence_delete on storage.objects for delete to authenticated using(bucket_id='labelproof-evidence' and lp_private.member_role(((storage.foldername(name))[1])::uuid)='admin');
create index lp_orgs_created_by_idx on public.lp_orgs(created_by);
create index lp_members_user_id_idx on public.lp_members(user_id);
create index lp_snapshots_updated_by_idx on public.lp_snapshots(updated_by);
create index lp_audit_org_at_idx on public.lp_audit(org_id,at);
create index lp_audit_actor_idx on public.lp_audit(actor);
create index lp_review_org_assessment_idx on public.lp_review_events(org_id,assessment_id);
create index lp_review_actor_idx on public.lp_review_events(actor);
